-- Custom IT skills + aliases seed for HR_Management / ITJob
-- Generated from current Skill + SkillAlias exports.
-- Safe behavior:
-- 1) Reuses existing Skill rows by LOWER(name)
-- 2) Inserts only missing Skill rows
-- 3) Inserts aliases only when no alias exists by LOWER(alias_text)
-- 4) Removes unsafe BI alias that caused false-positive matches from Vietnamese text like "tieu bieu"

ROLLBACK;

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TEMP TABLE tmp_custom_it_skill_seed (
  name TEXT NOT NULL,
  category TEXT,
  source TEXT,
  description TEXT,
  aliases TEXT
) ON COMMIT DROP;

;

-- Insert missing skills only. If ESCO already has a skill with the same name, keep the old row.
  id,
  name,
  is_active,
  source,
  description,
  created_at,
  updated_at
)
SELECT
  gen_random_uuid(),
  TRIM(t.name),
  TRUE,
  COALESCE(NULLIF(TRIM(t.source), ''), 'CUSTOM_IT_TREND_2026'),
  NULLIF(TRIM(t.description), ''),
  NOW(),
  NOW()
FROM tmp_custom_it_skill_seed t
WHERE NOT EXISTS (
  SELECT 1
  FROM "Skill" s
  WHERE LOWER(TRIM(s.name)) = LOWER(TRIM(t.name))
);

-- Add aliases for both existing ESCO skills and newly inserted custom skills.
-- This is the important part for CV/JD matching.
  id,
  skill_id,
  alias_text,
  created_at
)
SELECT DISTINCT ON (LOWER(TRIM(a.alias_text)))
  gen_random_uuid(),
  s.id,
  TRIM(a.alias_text),
  NOW()
FROM tmp_custom_it_skill_seed t
JOIN "Skill" s
  ON LOWER(TRIM(s.name)) = LOWER(TRIM(t.name))
CROSS JOIN LATERAL unnest(string_to_array(COALESCE(t.aliases, ''), ';')) AS a(alias_text)
WHERE
  TRIM(a.alias_text) <> ''
  AND LENGTH(REGEXP_REPLACE(TRIM(a.alias_text), '[^A-Za-z0-9+#.]', '', 'g')) >= 3
ORDER BY
  LOWER(TRIM(a.alias_text)),
  LOWER(TRIM(t.name))
ON CONFLICT (alias_text) DO NOTHING;

-- Avoid dangerous short alias that matched Vietnamese broken text: "tieu bieu" -> "bi".
DELETE FROM "SkillAlias"
WHERE LOWER(TRIM(alias_text)) = 'bi';

COMMIT;

